package net.civeira.phylax.feature.observe.observedslo.domain.gateway;

import java.util.List;
import java.util.Optional;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.feature.observe.observedslo.domain.ObservedSlo;
import net.civeira.phylax.feature.observe.observedslo.domain.ObservedSloRef;

public interface ObservedSloQueryRepositoryGateway {

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @return The items that would be returned by the query
   */
  long count(ObservedSloFilter filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param uid
   * @param filter a filter to retrieve only matching values
   * @return Retrieve one single value
   */
  boolean exists(String uid, Optional<ObservedSloFilter> filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @return The slide with some values
   */
  Optional<ObservedSlo> find(ObservedSloFilter filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @return The slide with some values
   */
  List<ObservedSlo> list(ObservedSloFilter filter);

  /**
   * Retrieve full data for a reference.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param reference a filter to retrieve only matching values
   * @return Retrieve one single value
   */
  ObservedSlo resolve(ObservedSloRef reference);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param uid
   * @param filter a filter to retrieve only matching values
   * @return Retrieve one single value
   */
  Optional<ObservedSlo> retrieve(String uid, Optional<ObservedSloFilter> filter);

  /**
   * Recover a slide of data.
   *
   * @autogenerated QueryRepositoryGatewayGenerator
   * @param filter a filter to retrieve only matching values
   * @param cursor a cursor to order and skip
   * @return The slide with some values
   */
  Slider<ObservedSlo> slide(ObservedSloFilter filter, ObservedSloCursor cursor);
}
